#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
vector<long long>a(n),b(m);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
for(int i=0;i<m;++i)scanf("%lld",&b[i]);
vector<long long>r(n+m);
int i=n-1,j=m-1,k=n+m-1;
while(j>=0){if(i>=0&&a[i]>b[j])r[k--]=a[i--];else r[k--]=b[j--];}
while(i>=0)r[k--]=a[i--];
for(int t=0;t<n+m;++t){if(t)printf(" ");printf("%lld",r[t]);}
printf("\n");return 0;}

